<template>
 <section class="fulfillment">
  <el-alert v-if="pendingRequest" :title="pendingRequest.kind==='RESTORE'?'已释放余量的恢复申请待审核，审核通过后重新检查库存并占用。':'已提交继续申请：保留剩余占用，等待原仓库执行结束后追加下一次执行。'" type="warning" :closable="false"/>
  <el-alert v-if="detail.pending_messages.length" title="存在明细未齐的仓库回传：当前不扣账，也不能停止或继续。请联系仓库补齐同一消息。" type="warning" :closable="false"/>
  <div class="tracks"><article><span>仓库执行</span><b>{{detail.executions.length}} 次</b><small>{{detail.state==='COMPLETED'?'原计划已全部出库扣账':detail.state==='CANCELED'?'未出余量已停止并释放':'按原计划执行，可分次出库'}}</small></article><article><span>包裹与物流</span><b>{{detail.parcels.length}} 个已识别包裹</b><small>{{parcelPending}} 个包裹待补齐或核对；{{unknownExecutions}} 次执行尚无包裹明细</small></article><article><span>供应商商品验收</span><b>{{units('pendingSupplier')}} 待确认</b><small>物流签收后仍需确认实际商品</small></article><article><span>供应商款项</span><b>¥{{money(detail.funds_remaining)}} 待核对</b><small>按实际退仓净货值登记凭证</small></article></div>
  <el-tabs v-model="tab">
   <el-tab-pane label="商品与库存" name="goods">
    <el-alert title="原计划保持不变。继续退仓沿用剩余占用；恢复已释放余量须另行审核。累计占用和累计释放保留各轮操作记录。" type="info" :closable="false"/>
    <el-table :data="detail.lines" size="small"><el-table-column label="商品 / 原入库来源" min-width="270"><template slot-scope="{row}"><strong>{{row.goods_name}}</strong><div class="muted">{{row.sku_sn}}<br>{{row.ticket_sn}} · {{row.source_key}}</div></template></el-table-column><el-table-column label="原批次 / 质量" min-width="160"><template slot-scope="{row}">{{row.batch_code}}<div>{{grade(row.inventory_type)}}</div></template></el-table-column><el-table-column label="原计划 / 实出 / 已扣账" min-width="190"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="当前占用 / 累计释放" min-width="170"><template slot-scope="{row}">{{stockFor(row)?held(stockFor(row)):'待确认'}} / {{stockFor(row)?stockFor(row).released_quantity:'待确认'}} {{row.stock_unit}}</template></el-table-column><el-table-column label="原采购单价 / 已独立收回" min-width="180"><template slot-scope="{row}">¥{{money(row.purchase_price)}}<div>{{row.recovered_quantity||0}} {{row.stock_unit}}</div></template></el-table-column></el-table>
    <el-collapse class="space"><el-collapse-item title="查看各轮库存占用与释放累计" name="stock"><el-table :data="stockRows" size="small" empty-text="尚未确认库存占用"><el-table-column prop="sku_sn" label="SKU" min-width="220"/><el-table-column prop="planned_quantity" label="原计划上限"/><el-table-column prop="quantity" label="累计占用"/><el-table-column prop="consumed_quantity" label="已出库扣减"/><el-table-column prop="released_quantity" label="累计释放"/><el-table-column label="当前占用"><template slot-scope="{row}">{{held(row)}}</template></el-table-column><el-table-column prop="recovered_quantity" label="拒收收回"/></el-table></el-collapse-item></el-collapse>
   </el-tab-pane>
   <el-tab-pane label="仓库执行" name="warehouse">
    <div class="toolbar"><el-button v-if="canContinue" v-hasPermi="['warehouse:purchaseReturn:continue']" type="primary" size="small" @click="open('REMAINING')">{{detail.state==='CANCELED'?'申请恢复已释放余量':'继续退剩余数量'}}</el-button><el-button v-if="canStop" v-hasPermi="['warehouse:purchaseReturn:cancel']" size="small" @click="open('STOP')">停止剩余并释放占用</el-button><el-button v-hasPermi="['warehouse:wms:log']" size="small" @click="logsOpen=!logsOpen">查看下发、查询与停止交互</el-button></div>
    <el-card v-for="e in detail.executions" :key="e.id" shadow="never" class="execution"><div slot="header" class="execution-header"><div><b>第 {{e.sequence_no}} 次执行</b><span class="muted">{{e.execution_sn}}</span></div><el-tag size="small" :type="e.state==='ACTIVE'?'primary':'info'">{{e.state==='ACTIVE'?'执行中':e.state==='ENDED'?'仓库最终确认':'仓库已停止'}}</el-tag></div><el-descriptions :column="4" size="small"><el-descriptions-item label="仓库受理">{{dispatch[e.dispatch_state]||e.dispatch_state}}</el-descriptions-item><el-descriptions-item label="原仓库单号">{{e.external_order||'尚未提供'}}</el-descriptions-item><el-descriptions-item label="库存来源">{{{INITIAL:'首次占用',EXISTING:'沿用剩余占用',REHOLD:'重新审核恢复占用'}[e.hold_action]}}</el-descriptions-item><el-descriptions-item label="本次最终确认">{{e.receipt_final?'已确认，短出余量可继续处理':'尚未收到'}}</el-descriptions-item></el-descriptions><p v-if="e.waybill" class="muted">头部运单 {{e.carrier_code}} · {{e.waybill}}；包裹及商品明细见“包裹与物流”。</p><el-alert v-if="e.last_error" :title="e.last_error" type="warning" :closable="false"/><el-table :data="e.lines" size="small"><el-table-column label="实际商品 / 原来源" min-width="260"><template slot-scope="{row}">{{row.goods_name}}<div class="muted">{{row.sku_sn}} · {{row.batch_code}} · {{grade(row.inventory_type)}}</div></template></el-table-column><el-table-column label="本次计划 / 实出 / 已扣账" min-width="200"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="供应商接受 / 拒收" min-width="160"><template slot-scope="{row}">{{row.supplier_accepted}} / {{row.supplier_refused}} {{row.stock_unit}}</template></el-table-column></el-table><el-button v-if="Number(detail.outbound_mode)===1&&!['UNSENT','PENDING','SENDING'].includes(e.dispatch_state)" v-hasPermi="['warehouse:purchaseReturn:queryWarehouse']" type="text" :loading="busy" @click="queryExecution(e)">查询本次仓库执行</el-button></el-card>
    <el-table v-if="detail.execution_requests.length" :data="detail.execution_requests" size="small"><el-table-column label="余量申请"><template slot-scope="{row}">{{row.kind==='RESTORE'?'恢复已释放余量':'沿用占用继续'}}</template></el-table-column><el-table-column label="当前进度"><template slot-scope="{row}">{{{REVIEW:'恢复待审核',WAIT_STOP:'等待原执行结束',CREATED:'已追加执行',REJECTED:'已驳回'}[row.state]}}</template></el-table-column><el-table-column prop="reason" label="依据" min-width="240"/><el-table-column label="申请 / 审核人"><template slot-scope="{row}">{{row.actor}} / {{row.reviewed_by||'尚无'}}</template></el-table-column><el-table-column label="操作"><template slot-scope="{row}"><el-button v-if="row.state==='REVIEW'" v-hasPermi="['warehouse:purchaseReturn:restoreApprove']" type="text" :loading="busy" @click="approveRestore(row)">审核恢复原计划余量</el-button></template></el-table-column></el-table>
    <el-table v-if="detail.pending_messages.length" :data="detail.pending_messages" size="small"><el-table-column prop="message_id" label="明细未齐的原回传消息"/><el-table-column prop="expected_lines" label="本消息应含商品行数"/><el-table-column prop="part_count" label="已收到不同分片数"/></el-table>
    <warehouse-interactions v-if="logsOpen" ref="logs" :sn="detail.return_sn"/>
   </el-tab-pane>
   <el-tab-pane label="包裹与物流" name="parcels">
    <p class="muted">同一个运单可以包含多个包裹。包裹商品与仓库实际出库分别核对；补录物流或关联原行不会再次扣减库存。</p><el-button v-if="detail.executions.length" v-hasPermi="['warehouse:purchaseReturn:parcel']" size="small" @click="open('PARCEL')">补录包裹与商品</el-button>
    <el-card v-for="p in detail.parcels" :key="p.id" shadow="never" class="execution"><div slot="header" class="execution-header"><div><b>包裹 {{p.package_code}}</b><div class="muted">{{p.execution_sn}} · {{p.carrier_name||p.carrier_code||'快递待补充'}} · {{p.waybill||'运单待补充'}}</div><div class="muted">原始 WMS 编码：{{p.carrier_code||'未提供'}} · OMS：{{carrierInfo(p).standard_name||'待识别'}} <el-tag size="mini" :type="p.carrier_resolution_state==='RESOLVED'?'success':'warning'">{{p.carrier_resolution_state==='RESOLVED'?'身份已识别':'物流对照待处理'}}</el-tag></div></div><el-tag size="small" :type="p.content_state==='MAPPED'?'success':'warning'">{{{MAPPED:'商品归属完整',PENDING:'商品待补齐',REVIEW:'原行归属待核对',CONFLICT:'回传内容冲突'}[p.content_state]}}</el-tag></div><el-alert v-if="p.content_state==='CONFLICT'" :title="p.evidence" type="warning" :closable="false"/><el-table :data="p.items" size="small" empty-text="仓库未提供本包裹商品，无法确定商品归属"><el-table-column label="仓库回传商品" min-width="220"><template slot-scope="{row}">{{row.sku_sn}}<div class="muted">{{row.quantity}} 个库存单位，具体单位见原行</div></template></el-table-column><el-table-column label="已确认原行 / 批次 / 质量" min-width="330"><template slot-scope="{row}"><div v-for="a in row.allocations" :key="a.id">{{a.goods_name}} · {{a.batch_code}} · {{grade(a.inventory_type)}} · {{a.quantity}} {{a.stock_unit}}<span class="muted">；供应商已确认 {{a.supplier_confirmed}}</span></div><span v-if="row.unassigned_quantity" class="warning">尚有 {{row.unassigned_quantity}} 待关联原行</span></template></el-table-column><el-table-column label="操作" width="140"><template slot-scope="{row}"><el-button v-if="row.unassigned_quantity&&p.content_state!=='CONFLICT'" v-hasPermi="['warehouse:purchaseReturn:parcel']" type="text" @click="open('ALLOCATE',{...row,execution_id:p.execution_id})">核对商品归属</el-button></template></el-table-column></el-table><el-button v-hasPermi="['warehouse:purchaseReturn:parcel']" type="text" @click="open('PARCEL',p)">{{p.items.length?'补充物流信息':'补齐包裹商品'}}</el-button></el-card><el-empty v-if="!detail.parcels.length" description="尚无已识别包裹；头部运单不代表已提供包裹商品明细"/>
   </el-tab-pane>
   <el-tab-pane label="供应商收货与收回" name="supplier">
    <div class="toolbar"><el-button v-if="Number(detail.posted_quantity)>0" v-hasPermi="['warehouse:purchaseReturn:supplierReceipt']" type="primary" size="small" @click="open('SUPPLIER')">登记商品接受 / 拒收 / 短收</el-button><el-button v-if="refusals.length" v-hasPermi="['warehouse:purchaseReturn:reclaimCreate']" size="small" @click="open('RECLAIM')">按拒收来源创建收回入库</el-button></div>
    <el-alert title="按实际商品验收登记。无法确定包裹时可先选择仓库执行行，之后补关联包裹；补关联不会重复增加收货或拒收数量。" type="info" :closable="false"/>
    <el-table :data="detail.supplier_sources" size="small" empty-text="尚未登记供应商实际商品验收"><el-table-column label="商品 / 原批次 / 执行" min-width="300"><template slot-scope="{row}"><b>{{row.goods_name}}</b><div class="muted">{{row.sku_sn}} · {{row.batch_code}} · {{grade(row.inventory_type)}}<br>{{row.execution_sn}} · 拒收/收货来源 #{{row.id}}</div></template></el-table-column><el-table-column label="实际商品结果" min-width="140"><template slot-scope="{row}">{{{ACCEPT:'接受',REFUSE:'拒收',SHORT:'短收待核对'}[row.decision]}} {{row.quantity}} {{row.stock_unit}}</template></el-table-column><el-table-column label="已关联包裹 / 尚未关联" min-width="260"><template slot-scope="{row}"><div v-for="b in row.parcel_bindings" :key="b.id">{{b.package_code}} · {{b.waybill||'运单待补充'}} · {{b.quantity}} {{row.stock_unit}}</div><span v-if="row.unbound_quantity" class="warning">{{row.unbound_quantity}} {{row.stock_unit}} 未关联包裹</span><span v-if="row.decision==='SHORT'" class="muted">仅保留核对证据</span></template></el-table-column><el-table-column label="收回进度 / 凭证" min-width="220"><template slot-scope="{row}"><div v-if="row.decision==='REFUSE'">已安排 {{row.reclaim_claimed}} · 尚可安排 {{row.reclaim_available}} {{row.stock_unit}}</div><div class="muted">{{row.evidence}}</div></template></el-table-column><el-table-column label="操作" width="120"><template slot-scope="{row}"><el-button v-if="row.unbound_quantity" v-hasPermi="['warehouse:purchaseReturn:supplierReceipt']" type="text" @click="open('BIND',row)">补关联包裹</el-button></template></el-table-column></el-table>
    <h3>拒收收回入库单</h3><el-table :data="detail.reclaims" size="small"><el-table-column label="收回单号 / 具体来源" min-width="300"><template slot-scope="{row}"><el-button type="text" @click="$emit('reclaim',row.id)">{{row.reclaim_sn}}</el-button><div class="muted">详情按原拒收来源分别跟踪实收</div></template></el-table-column><el-table-column label="计划 / 实收 / 已入账"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}}<div class="muted">单位见收回明细</div></template></el-table-column><el-table-column label="仓库进度"><template slot-scope="{row}">{{dispatch[row.dispatch_state]||row.dispatch_state}}<div class="muted">{{row.state==='COMPLETED'?'实收已入账':row.state==='DRAFT'?'待审核':row.state==='CANCELED'?'剩余已停止':'收回处理中'}}</div></template></el-table-column><el-table-column label="供应商退回物流"><template slot-scope="{row}">{{carrierInfo(row).standard_name||'标准快递待识别'}} · {{row.waybill}}<div class="muted">WMS 入库编码：{{row.carrier_code||'尚未确认'}}</div><div class="warning">{{row.last_error}}</div></template></el-table-column></el-table>
   </el-tab-pane>
   <el-tab-pane label="款项与处理记录" name="funds"><slot name="funds"/><h3>处理记录</h3><el-table :data="detail.audit" size="small"><el-table-column prop="create_time" label="时间" width="175"/><el-table-column prop="actor" label="处理人" width="130"/><el-table-column label="处理动作" width="170"><template slot-scope="{row}">{{auditLabels[row.action]||row.action}}</template></el-table-column><el-table-column prop="reason" label="处理结果与依据" min-width="340"/></el-table></el-tab-pane>
  </el-tabs>
  <el-dialog :title="titles[kind]" :visible.sync="visible" width="min(1100px,96vw)" append-to-body :close-on-click-modal="false">
   <el-alert :title="hints[kind]" type="info" :closable="false"/>
   <el-table v-if="['REMAINING','STOP'].includes(kind)" :data="detail.lines.filter(l=>Number(l.quantity)>Number(l.posted_quantity))" size="small" class="space"><el-table-column label="原商品 / 批次 / 质量" min-width="280"><template slot-scope="{row}">{{row.goods_name}}<div class="muted">{{row.sku_sn}} · {{row.batch_code}} · {{grade(row.inventory_type)}}</div></template></el-table-column><el-table-column label="原计划 / 已扣账 / 尚未出库" min-width="220"><template slot-scope="{row}">{{row.quantity}} / {{row.posted_quantity}} / {{Number(row.quantity)-Number(row.accepted_quantity)}} {{row.stock_unit}}</template></el-table-column><el-table-column label="当前占用处理" min-width="220"><template slot-scope="{row}">{{detail.state==='CANCELED'?'已释放，审核后重新校验并占用':kind==='STOP'?'确认原执行停止后释放':'原剩余占用持续保留'}}<div class="muted">当前 {{stockFor(row)?held(stockFor(row)):'待确认'}} {{row.stock_unit}}</div></template></el-table-column></el-table>
   <el-form label-position="top" size="small" class="space">
    <template v-if="kind==='SUPPLIER'"><el-form-item label="实际商品结果"><el-radio-group v-model="decision"><el-radio label="ACCEPT">接受商品</el-radio><el-radio label="REFUSE">拒收商品</el-radio><el-radio label="SHORT">短收待核对</el-radio></el-radio-group></el-form-item><el-form-item label="收货来源"><el-radio-group v-model="sourceType" @change="sourceRows"><el-radio label="parcel">明确到包裹商品</el-radio><el-radio label="execution">先登记到仓库执行商品行</el-radio></el-radio-group></el-form-item></template>
    <el-table v-if="['SUPPLIER','RECLAIM'].includes(kind)" :data="rows" size="small"><el-table-column label="原商品 / 批次 / 质量" min-width="260"><template slot-scope="{row}"><b>{{row.goods_name}}</b><div class="muted">{{row.sku_sn}} · {{row.batch_code}} · {{grade(row.inventory_type)}}<br>{{row.execution_sn}}</div></template></el-table-column><el-table-column label="具体来源" min-width="230"><template slot-scope="{row}">{{kind==='RECLAIM'?'拒收来源 #'+row.id:sourceType==='parcel'?'包裹 '+row.package_code:'执行商品行 #'+row.id}}<div class="muted">{{row.waybill||''}}</div></template></el-table-column><el-table-column label="本次可登记" width="130"><template slot-scope="{row}">{{row.limit}} {{row.stock_unit}}</template></el-table-column><el-table-column label="本次数量" width="180"><template slot-scope="{row}"><el-input-number v-model="row.selected" :min="0" :max="row.limit" :precision="0" size="small"/></template></el-table-column></el-table>
    <template v-if="kind==='PARCEL'"><el-form-item label="所属仓库执行" required><el-select v-model="form.execution_id" :disabled="!!original" @change="parcelRows"><el-option v-for="e in detail.executions" :key="e.id" :value="e.id" :label="'第'+e.sequence_no+'次 · '+e.execution_sn"/></el-select></el-form-item><el-form-item label="仓库包裹编号" required><el-input v-model.trim="form.package_code" :disabled="!!original" maxlength="128" placeholder="填写仓库实际包裹编号"/></el-form-item><el-form-item label="仓库原始快递编码 / 运单号"><div class="inline"><el-input v-model="form.carrier_code" maxlength="128" placeholder="登记原始编码，未识别时保留待办"/><el-input v-model.trim="form.waybill" :disabled="!!(original&&original.waybill)" maxlength="128" placeholder="本包裹实际运单号"/></div></el-form-item><el-form-item v-if="original&&original.content_state==='CONFLICT'" label="确认原商品事实"><el-checkbox v-model="form.confirm_original">已核对仓库更正凭证，确认保留当前已登记的包裹商品</el-checkbox><div class="muted">本操作保留原商品、批次和已有验收，不使用冲突回传覆盖事实；请在下方填写更正凭证。</div></el-form-item><template v-if="!original||!original.items.length"><p class="muted">选择包裹内实际商品并填写数量。只补运单时可保留商品数量为0，稍后继续补齐。</p><el-table :data="rows" size="small"><el-table-column label="该执行原商品与批次" min-width="330"><template slot-scope="{row}">{{row.goods_name}} · {{row.sku_sn}}<div class="muted">{{row.batch_code}} · {{grade(row.inventory_type)}}</div></template></el-table-column><el-table-column label="本包裹数量" width="190"><template slot-scope="{row}"><el-input-number v-model="row.selected" :min="0" :max="row.accepted_quantity" :precision="0" size="small"/> {{row.stock_unit}}</template></el-table-column></el-table></template></template>
    <template v-if="['ALLOCATE','BIND'].includes(kind)"><el-form-item :label="kind==='ALLOCATE'?'明确原执行商品行（批次、质量、成本）':'明确已识别的包裹商品'" required><el-select v-model="target" filterable style="width:100%"><el-option v-for="r in choices" :key="r.id" :value="r.id" :label="choiceLabel(r)"/></el-select></el-form-item><el-form-item label="本次关联数量" required><el-input-number :key="kind+'-'+target" v-model="quantity" :min="1" :max="targetLimit" :precision="0" :disabled="targetLimit<1"/><span class="muted"> 最多 {{targetLimit}}；关联不调整库存及已有收货数量。</span></el-form-item></template>
    <return-carrier-capture v-if="kind==='RECLAIM'" v-model="form" :purchase-id="detail.purchase_id" :active="visible"/>
    <el-form-item label="核对依据 / 处理原因" required><el-input v-model.trim="evidence" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item>
   </el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><span slot="footer"><el-button :disabled="busy" @click="visible=false">返回</el-button><el-button type="primary" :loading="busy" @click="submit">{{kind==='REMAINING'?(detail.state==='CANCELED'?'提交恢复审核申请':'确认同单继续退仓'):kind==='STOP'?'停止剩余并释放占用':kind==='RECLAIM'?'保存收回入库草稿':'保存核对结果'}}</el-button></span>
  </el-dialog>
  <purchase-return-restore ref="restore" :detail="detail" @approved="$emit('changed')"/>
 </section>
</template>
<script>
import ReturnCarrierCapture from './ReturnCarrierCapture'
import { carrierInfo } from '@/utils/carrierPresentation'
import {returnAction} from '@/api/purchase/returns'
import WarehouseInteractions from '../order/ReturnInteractionPanel'
import PurchaseReturnRestore from './PurchaseReturnRestore'
import PurchaseReturnCarrierSelect from './PurchaseReturnCarrierSelect'
const key=()=> 'PRE'+Date.now()+Math.random().toString(36).slice(2)
export default {
 components:{ReturnCarrierCapture,WarehouseInteractions,PurchaseReturnRestore,PurchaseReturnCarrierSelect},props:{detail:{type:Object,required:true}},
 data:()=>({tab:'goods',logsOpen:false,busy:false,visible:false,kind:'',original:null,rows:[],evidence:'',error:'',requestKey:'',version:0,form:{},decision:'ACCEPT',sourceType:'parcel',target:null,quantity:1,dispatch:{UNSENT:'尚未下发',PENDING:'等待下发',SENDING:'下发待确认',UNKNOWN:'原下发结果不明',ACCEPTED:'仓库已受理',FAILED:'仓库明确拒绝',CANCELED:'仓库已停止',VIRTUAL:'自动虚拟执行'},titles:{REMAINING:'同一退仓单继续剩余数量',STOP:'停止剩余退仓',PARCEL:'补充包裹与商品',ALLOCATE:'核对包裹商品原行归属',SUPPLIER:'登记供应商实际商品验收',BIND:'已有商品验收补关联包裹',RECLAIM:'按具体拒收来源安排收回入库'},hints:{REMAINING:'保留同一个CGT。原执行尚未结束时先确认仓库停止；有效剩余占用沿用，已经释放则另行审核恢复。',STOP:'保留已出库、已扣账和供应商验收事实。仓库确认原执行结束后，仅释放未出库占用。',PARCEL:'只补充缺失的原始物流与装箱信息，不产生出库扣账；已有原始物流和商品事实不能覆盖。',ALLOCATE:'同SKU存在多个批次或来源时须明确原行，不能按顺序猜测。',SUPPLIER:'物流签收不代表商品验收。短收仅记录核对证据；接受和拒收合计不能超过已实际出库扣账。',BIND:'将已有接受或拒收事实关联到包裹，不再次增加验收数量或可收回额度。',RECLAIM:'逐条选择真实拒收来源，保留原批次、质量和成本。审核后下发，仓库实收后才恢复库存。'},auditLabels:{CREATE:'创建草稿',APPROVE:'审核退仓',EXECUTION_CREATED:'追加仓库执行',OUTBOUND_ACCEPTED:'确认实际出库',CONTINUE_REQUEST:'申请同单继续',RESTORE_REQUEST:'申请恢复已释放余量',RESTORE_APPROVE:'审核恢复余量',STOP_REQUEST:'申请停止剩余',STOP_CONFIRMED:'确认停止并释放',RETRY:'重试原执行',PARCEL_SUPPLEMENT:'补齐包裹物流',PARCEL_ALLOCATE:'明确包裹商品归属',SUPPLIER_BIND:'已有验收补关联包裹',SUPPLIER_ACCEPT:'供应商接受商品',SUPPLIER_REFUSE:'供应商拒收商品',SUPPLIER_SHORT:'供应商短收待核对',RECLAIM_CREATE:'创建拒收收回',RECLAIM_APPROVE:'审核拒收收回',RECLAIM_RECEIPT:'仓库确认收回实收',RECLAIM_CANCEL:'停止剩余收回',RECLAIM_RETRY:'重试收回步骤',FUNDS_RECORD:'登记款项凭证',FUNDS_REVERSAL:'追加凭证冲销'}}),
 computed:{unknownExecutions(){return this.detail.executions.filter(e=>Number(e.accepted_quantity)>0&&!this.detail.parcels.some(p=>Number(p.execution_id)===Number(e.id))).length},stockRows(){return this.detail.stock&&this.detail.stock.lines||[]},pendingRequest(){return this.detail.execution_requests.find(r=>['REVIEW','WAIT_STOP'].includes(r.state))},canContinue(){return ['APPROVED','CANCELED'].includes(this.detail.state)&&Number(this.detail.quantity)>Number(this.detail.accepted_quantity)&&Number(this.detail.accepted_quantity)===Number(this.detail.posted_quantity)&&!this.detail.receipt_review_pending&&!this.pendingRequest},canStop(){return ['APPROVING','APPROVED'].includes(this.detail.state)&&!this.pendingRequest&&!this.detail.receipt_review_pending},parcelPending(){return this.detail.parcels.filter(p=>p.content_state!=='MAPPED').length},refusals(){return this.detail.supplier_sources.filter(s=>s.decision==='REFUSE'&&Number(s.reclaim_available)>0)},choices(){if(this.kind==='BIND')return this.detail.parcel_allocations.filter(a=>a.parcel_state!=='CONFLICT'&&Number(a.execution_line_id)===Number(this.original.execution_line_id)&&Number(a.quantity)>Number(a.supplier_confirmed));if(this.kind==='ALLOCATE')return this.detail.execution_lines.filter(l=>Number(l.execution_id)===Number(this.original.execution_id)&&l.sku_sn===this.original.sku_sn);return []},targetLimit(){const row=this.choices.find(x=>Number(x.id)===Number(this.target));if(!row)return 0;if(this.kind==='BIND')return Math.min(Number(this.original.unbound_quantity),Number(row.quantity)-Number(row.supplier_confirmed));const assigned=this.detail.parcel_allocations.filter(a=>a.parcel_state!=='CONFLICT'&&Number(a.execution_line_id)===Number(row.id)).reduce((v,a)=>v+Number(a.quantity),0);return Math.min(Number(this.original.unassigned_quantity),Number(row.accepted_quantity)-assigned)}},
 methods:{carrierInfo,money(v){return Number(v||0).toFixed(2)},grade(v){return v==='ZP'?'正品':'次品'},held(row){return Number(row.quantity)-Number(row.consumed_quantity)-Number(row.released_quantity)},stockFor(row){return this.stockRows.find(s=>Number(s.line_key)===Number(row.id))},units(key){const totals={};for(const l of this.detail.lines){const q=key==='pendingSupplier'?Math.max(0,Number(l.posted_quantity)-Number(l.supplier_received_quantity)-Number(l.supplier_refused_quantity)):Number(l[key]||0);totals[l.stock_unit]=(totals[l.stock_unit]||0)+q}return Object.keys(totals).filter(k=>totals[k]>0).map(k=>totals[k]+' '+k).join(' + ')||'0'},
  async queryExecution(e){if(this.busy)return;this.busy=true;try{await returnAction(this.detail.id,'executions/'+e.id+'/query');this.$emit('changed')}finally{this.busy=false}},approveRestore(r){this.$refs.restore.open(r)},
  async openLog(id){this.tab='warehouse';this.logsOpen=true;await this.$nextTick();if(id&&this.$refs.logs)this.$refs.logs.show(id)},open(kind,original){this.kind=kind;this.original=original||null;this.error='';this.evidence='';this.requestKey=key();this.version=this.detail.control_version;this.target=null;this.quantity=1;this.decision='ACCEPT';this.sourceType=this.detail.parcel_allocations.length?'parcel':'execution';this.form={execution_id:original&&original.execution_id||this.detail.executions[0]&&this.detail.executions[0].id,package_code:original&&original.package_code||'',standard_id:'',carrier_unverified:false,raw_carrier_code:'',raw_carrier_name:'',carrier_code:original&&original.carrier_code||'',waybill:original&&original.waybill||''};this.rows=[];if(kind==='SUPPLIER')this.sourceRows();if(kind==='PARCEL')this.parcelRows();if(kind==='RECLAIM')this.rows=this.refusals.map(r=>({...r,selected:0,limit:Number(r.reclaim_available)}));this.visible=true},
  sourceRows(){const rows=this.sourceType==='parcel'?this.detail.parcel_allocations.filter(a=>a.parcel_state!=='CONFLICT'):this.detail.execution_lines;this.rows=rows.map(r=>{const execution=this.sourceType==='parcel'?this.detail.execution_lines.find(l=>Number(l.id)===Number(r.execution_line_id)):r;const remaining=execution?Number(execution.posted_quantity)-Number(execution.supplier_accepted)-Number(execution.supplier_refused):0;return {...r,selected:0,limit:Math.max(0,Math.min(remaining,this.sourceType==='parcel'?Number(r.quantity)-Number(r.supplier_confirmed):remaining))}}).filter(r=>r.limit>0)},parcelRows(){this.rows=this.detail.execution_lines.filter(l=>Number(l.execution_id)===Number(this.form.execution_id)).map(l=>({...l,selected:0}))},choiceLabel(r){return (this.kind==='BIND'?'包裹 '+r.package_code+' · '+(r.waybill||'运单待补充'):'原行 #'+r.id)+' · '+r.sku_sn+' · '+r.batch_code+' · '+this.grade(r.inventory_type)},
  async submit(){if(this.busy)return;if(!this.evidence.trim())return this.$message.warning('请填写核对依据');const body={request_key:this.requestKey,control_version:this.version,evidence:this.evidence,reason:this.evidence};let action;
   if(['REMAINING','STOP'].includes(this.kind)){action=this.kind==='STOP'?'cancel':'continue';if(body.reason.length>200&&action==='cancel')return this.$message.warning('停止原因最多200字')}
   else if(this.kind==='PARCEL'){if(!this.form.package_code)return this.$message.warning('请填写仓库实际包裹编号');action='parcels/supplement';Object.assign(body,this.form,{parcel_version:this.original&&this.original.control_version,items:this.rows.filter(r=>r.selected>0).map(r=>({sku_sn:r.sku_sn,line_key:r.id,batch_code:r.batch_code,inventory_type:r.inventory_type,quantity:r.selected}))})}
   else if(this.kind==='ALLOCATE'){if(!this.target||this.quantity<1||this.quantity>this.targetLimit)return this.$message.warning('请核对原行和可关联数量');action='parcels/allocate';body.lines=[{item_id:this.original.id,execution_line_id:this.target,quantity:this.quantity}]}
   else if(this.kind==='BIND'){if(!this.target||this.quantity<1||this.quantity>this.targetLimit)return this.$message.warning('请核对包裹商品和可关联数量');action='supplier-bind';body.lines=[{supplier_line_id:this.original.id,allocation_id:this.target,quantity:this.quantity}]}
   else{const selected=this.rows.filter(r=>Number(r.selected)>0);if(!selected.length)return this.$message.warning('请填写本次商品数量');if(this.kind==='RECLAIM'){if(!this.form.waybill||(!this.form.carrier_unverified&&!this.form.standard_id)||(this.form.carrier_unverified&&!this.form.raw_carrier_code&&!this.form.raw_carrier_name))return this.$message.warning('请填写供应商退回本仓的实际快递和运单');action='reclaims';Object.assign(body,this.form,{lines:selected.map(r=>({supplier_source_id:r.id,quantity:r.selected}))})}else{action='supplier-receipt';body.decision=this.decision;body.lines=selected.map(r=>({... (this.sourceType==='parcel'?{allocation_id:r.id}:{execution_line_id:r.id}),quantity:r.selected}))}}
   this.busy=true;this.error='';try{const r=await returnAction(this.detail.id,action,body);this.visible=false;this.$emit('changed');if(this.kind==='RECLAIM')this.$emit('reclaim',r.data)}catch(e){this.error=e.message||'保存未确认，请刷新原单'}finally{this.busy=false}}
 }
}
</script>
